# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SAHABENİN KUR\'AN-I KERİM\'E BAĞLILIĞI: ÖĞRENME, YAZMA VE HIFZ (2.3)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Öğrenme ve Öğretme</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Mekke Dönemi:</tspan> Dârü\'l-Erkam</text>\n  <text x="40" y="107" font-size="10.5" fill="#1e3a8a">ilk Kur\'an eğitim merkezi oldu.</text>\n  <text x="32" y="128" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Medine Dönemi:</tspan> Mescid-i</text>\n  <text x="40" y="143" font-size="10.5" fill="#1e3a8a">Nebevî ve <tspan font-weight="bold">Ashâb-ı Suffe</tspan> (Kurra</text>\n  <text x="40" y="158" font-size="10.5" fill="#1e3a8a">hafız ve muallimlerin yetiştiği okul).</text>\n  <rect x="32" y="175" width="186" height="50" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="125" y="194" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">"Sizin en hayırlınız Kur\'an\'ı</text>\n  <text x="125" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">öğrenen ve öğretendir." (Hadis)</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Ezberleme (Hıfz / Huffâz)</text>\n  <text x="257" y="92" font-size="10.5" fill="#14532d">• Sahabiler inen ayetleri hemen</text>\n  <text x="265" y="107" font-size="10.5" fill="#14532d">ezberleyip gece-gündüz namazda</text>\n  <text x="265" y="122" font-size="10.5" fill="#14532d">okuyarak (<tspan font-weight="bold">tilavet</tspan>) korudular.</text>\n  <text x="257" y="143" font-size="10.5" font-weight="bold" fill="#15803d">• Öncü Kurra Sahabiler:</text>\n  <text x="265" y="158" font-size="10" fill="#14532d">Abdullah bin Mes\'ûd, Übey bin</text>\n  <text x="265" y="173" font-size="10" fill="#14532d">Ka\'b, Muâz bin Cebel, Zeyd bin</text>\n  <text x="265" y="188" font-size="10" fill="#14532d">Sâbit, Ebû Mûsâ el-Eş\'arî,</text>\n  <text x="265" y="203" font-size="10" fill="#14532d">Sâlim (Mevlâ Ebî Huzeyfe).</text>\n  <text x="350" y="226" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Yemâme\'de 70 hafız şehit oldu!</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Yazma ve Kitaplaştırma</text>\n  <text x="482" y="92" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Vahiy Kâtipleri:</tspan> Zeyd bin Sâbit</text>\n  <text x="490" y="107" font-size="10.5" fill="#78350f">başta olmak üzere 40\'tan fazla</text>\n  <text x="490" y="122" font-size="10.5" fill="#78350f">kâtip inen ayetleri kayda geçirdi.</text>\n  <text x="482" y="143" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Cem\' (Hz. Ebû Bekir):</tspan> Zeyd b.</text>\n  <text x="490" y="158" font-size="10.5" fill="#78350f">Sâbit heyetiyle tek <tspan font-weight="bold">Mushaf</tspan> oldu.</text>\n  <text x="482" y="179" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">İstinsah (Hz. Osman):</tspan> Mushaf</text>\n  <text x="490" y="194" font-size="10.5" fill="#78350f">çoğaltılarak İslam merkezlerine</text>\n  <text x="490" y="209" font-size="10.5" font-weight="bold" fill="#b45309">gönderildi ve birlik korundu.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SAHABENİN KUR\'AN OKUMA VE ÖĞRENME YÖNTEMİ: "ON AYET METODU"</text>\n  <rect x="25" y="46" width="650" height="75" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">Abdullah bin Mes\'ûd (r.a.) ve Ebû Abdurrahman es-Sülemî\'nin Naklettiği Eğitim İlkesi:</text>\n  <text x="350" y="90" text-anchor="middle" font-size="11" font-style="italic" fill="#581c87">"Biz Resûlullah\'tan (s.a.v.) on ayet öğrendiğimizde, o ayetlerdeki ilmi ve ameli hayatımıza</text>\n  <text x="350" y="106" text-anchor="middle" font-size="11" font-style="italic" font-weight="bold" fill="#6b21a8">tam olarak uygulamadan sonraki on ayete geçmezdik. Böylece ilmi ve ameli birlikte öğrendik."</text>\n  <rect x="25" y="135" width="150" height="105" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="100" y="158" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. Tilavet ve Hıfz</text>\n  <text x="100" y="178" text-anchor="middle" font-size="10" fill="#1e3a8a">Ayetleri Peygamberimizden</text>\n  <text x="100" y="193" text-anchor="middle" font-size="10" fill="#1e3a8a">doğru telaffuzla dinleme</text>\n  <text x="100" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">ve kalbe nakşetme</text>\n  <path d="M 177 187 L 195 187" stroke="#2563eb" stroke-width="2.5"/>\n  <rect x="197" y="135" width="150" height="105" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="272" y="158" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. Tefekkür ve İlim</text>\n  <text x="272" y="178" text-anchor="middle" font-size="10" fill="#14532d">Ayetlerin anlamını, helal</text>\n  <text x="272" y="193" text-anchor="middle" font-size="10" fill="#14532d">ve haram hükümlerini</text>\n  <text x="272" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">derinlemesine kavrama</text>\n  <path d="M 349 187 L 367 187" stroke="#16a34a" stroke-width="2.5"/>\n  <rect x="369" y="135" width="150" height="105" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="444" y="158" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">3. Amel (Yaşama)</text>\n  <text x="444" y="178" text-anchor="middle" font-size="10" fill="#78350f">"İşittik ve itaat ettik"</text>\n  <text x="444" y="193" text-anchor="middle" font-size="10" fill="#78350f">diyerek ayeti hemen</text>\n  <text x="444" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">ahlaka ve hayata aktarma</text>\n  <path d="M 521 187 L 539 187" stroke="#d97706" stroke-width="2.5"/>\n  <rect x="541" y="135" width="134" height="105" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="608" y="158" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">4. Tebliğ</text>\n  <text x="608" y="178" text-anchor="middle" font-size="10" fill="#7f1d1d">Öğrenilen ve yaşanan</text>\n  <text x="608" y="193" text-anchor="middle" font-size="10" fill="#7f1d1d">ayetleri aileye ve diğer</text>\n  <text x="608" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">insanlara öğretme</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SAHABENİN KUR\'AN AHLAKIYLA YAŞAMA ÖRNEKLERİ (CANLI KUR\'AN TOPLUMU)</text>\n  <rect x="20" y="48" width="210" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Ebû Talha ve Sevilen İnfak</text>\n  <text x="32" y="94" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Âl-i İmrân 92. Ayet:</tspan> "Sevdiğiniz</text>\n  <text x="40" y="109" font-size="10.5" fill="#1e3a8a">mallardan Allah yolunda</text>\n  <text x="40" y="124" font-size="10.5" fill="#1e3a8a">harcamadıkça iyiliğe (birr\'e)</text>\n  <text x="40" y="139" font-size="10.5" fill="#1e3a8a">asla erişemezsiniz."</text>\n  <text x="32" y="162" font-size="10.5" fill="#1e3a8a">• Ayet inince <tspan font-weight="bold">Ebû Talha</tspan> Medine\'de</text>\n  <text x="40" y="177" font-size="10.5" fill="#1e3a8a">en çok sevdiği <tspan font-weight="bold">Beyruhâ</tspan> hurma</text>\n  <text x="40" y="192" font-size="10.5" font-weight="bold" fill="#1d4ed8">bahçesini hemen infak etti!</text>\n  <rect x="245" y="48" width="210" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Hz. Ebû Bekir ve Affedicilik</text>\n  <text x="257" y="94" font-size="10.5" fill="#14532d">• İfk hadisesine karışan akrabası</text>\n  <text x="265" y="109" font-size="10.5" fill="#14532d">Mıstah\'a yardımı kesmeye</text>\n  <text x="265" y="124" font-size="10.5" fill="#14532d">yemin etmişti.</text>\n  <text x="257" y="147" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Nûr Suresi 22. Ayet:</tspan> "Allah\'ın</text>\n  <text x="265" y="162" font-size="10.5" fill="#14532d">sizi bağışlamasını istemez misiniz?"</text>\n  <text x="265" y="177" font-size="10.5" fill="#14532d">inince <tspan font-weight="bold">"Vallahi isterim!"</tspan> diyerek</text>\n  <text x="265" y="192" font-size="10.5" font-weight="bold" fill="#15803d">yardımını yeniden başlattı.</text>\n  <rect x="470" y="48" width="210" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Yasaklardan Anında Vazgeçiş</text>\n  <text x="482" y="94" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Mâide 90–91. Ayetler:</tspan> İçki ve</text>\n  <text x="490" y="109" font-size="10.5" fill="#7f1d1d">kumarın kesin olarak haram</text>\n  <text x="490" y="124" font-size="10.5" fill="#7f1d1d">kılındığı tebliğ edildiği anda</text>\n  <text x="490" y="139" font-size="10.5" fill="#7f1d1d">sahabiler <tspan font-weight="bold">"Vazgeçtik Rabbimiz!"</tspan></text>\n  <text x="490" y="154" font-size="10.5" fill="#7f1d1d">diyerek küpleri döktüler.</text>\n  <text x="482" y="177" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Hucurât 2:</tspan> Sabit bin Kays\'ın</text>\n  <text x="490" y="192" font-size="10.5" font-weight="bold" fill="#b91c1c">derin takva ve edep hassasiyeti.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
